INSERT IGNORE INTO `page_translations` (`page_id`, `locale`, `title`, `seo_description`, `status`) VALUES (@p, 'en', 'Where am I on the expressway', 'Type the kilometre marker on the nearest post, or use your phone’s location, to find your position on the Dhaka Bypass Expressway and the nearest exit and toll plaza.', 'published');
INSERT IGNORE INTO `page_translations` (`page_id`, `locale`, `title`, `seo_description`, `status`) VALUES (@p, 'bn', 'এক্সপ্রেসওয়েতে আমি কোথায়', 'কাছের পোস্টের কিলোমিটার নম্বর লিখুন বা ফোনের লোকেশন ব্যবহার করুন: ঢাকা বাইপাস এক্সপ্রেসওয়েতে আপনার অবস্থান, কাছের এক্সিট ও টোল প্লাজা জানুন।', 'published');
