INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"eyebrow":"Travel information","heading":"Where am I on the expressway","lede":"Broken down, or asked where you are? The posts beside the road tell you. Type the marker and this page names the stretch, the nearest toll plaza and the next exit each way."}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"eyebrow":"যাতায়াত তথ্য","heading":"এক্সপ্রেসওয়েতে আমি কোথায়","lede":"গাড়ি নষ্ট হয়েছে, বা কেউ জিজ্ঞেস করছে আপনি কোথায়? রাস্তার পাশের পোস্টই বলে দেয়। পোস্টের নম্বর লিখুন, এই পেজ জানাবে কোন অংশে আছেন, কাছের টোল প্লাজা ও দুই দিকের পরের এক্সিট।"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"eyebrow":"出行信息","heading":"我在快速路的哪里","lede":"车辆抛锚，或有人问您在哪里？路边的公里桩会告诉您。输入桩号，本页即显示所在路段、最近的收费站和两个方向的下一个出口。"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
