INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"How to read the posts","body":"<p>Kilometre posts stand on the left verge every kilometre, counted from the Joydebpur end of the corridor. A post reading <strong>K12</strong> is twelve kilometres from the start; the smaller plates between them add the metres past the last full kilometre, so a plate reading <strong>+500</strong> after K12 is twelve and a half kilometres in. Bridges and toll plazas carry their own chainage on the structure.</p><p>If you cannot see a post, the last toll plaza you passed, the last bridge, or the button above (which asks your phone for its position) will do. The position from a phone is usually within a few tens of metres; the page says how far from the road it thinks you are.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"পোস্ট কীভাবে পড়বেন","body":"<p>কিলোমিটার পোস্ট রাস্তার বাঁ পাশে প্রতি কিলোমিটারে থাকে, করিডোরের জয়দেবপুর প্রান্ত থেকে গোনা। <strong>K12</strong> লেখা পোস্ট মানে শুরু থেকে বারো কিলোমিটার; মাঝের ছোট প্লেট শেষ পুরো কিলোমিটারের পর কত মিটার তা দেখায়, তাই K12-এর পর <strong>+500</strong> লেখা প্লেট মানে সাড়ে বারো কিলোমিটার। ব্রিজ ও টোল প্লাজায় নিজস্ব চেইনেজ লেখা থাকে।</p><p>পোস্ট দেখতে না পেলে শেষ যে টোল প্লাজা বা ব্রিজ পার হয়েছেন তা বলুন, বা ওপরের বাটনটি চাপুন (এটি ফোনের লোকেশন নেয়)। ফোনের লোকেশন সাধারণত কয়েক দশ মিটারের মধ্যে ঠিক থাকে; পেজ জানায় রাস্তা থেকে আপনাকে কত দূরে ধরছে।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"如何读公里桩","body":"<p>公里桩立在左侧路肩，每公里一个，从走廊的 Joydebpur 端起算。写着 <strong>K12</strong> 的桩表示距起点十二公里；中间较小的牌子表示距上一个整公里的米数，因此 K12 之后写着 <strong>+500</strong> 的牌子表示十二公里半处。桥梁和收费站在构造物上标有各自的桩号。</p><p>看不到公里桩时，可以说出最后经过的收费站或桥梁，或点击上方按钮（它会读取手机定位）。手机定位通常误差在几十米内；页面会说明它认为您距道路多远。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;

