INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"eyebrow":"যাতায়াত তথ্য","heading":"করিডোরের আবহাওয়া","lede":"শীতে গাজীপুর থেকে নারায়ণগঞ্জের মধ্যে ভোরের কুয়াশায় দৃষ্টিসীমা কয়েকশো মিটারে নেমে আসে, আর বর্ষার বৃষ্টিতে নিচু অংশে পানি জমে। রওনা হওয়ার আগে এখানে দেখে নিন।"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
