INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Driving in fog","body":"<p>Fog on this corridor is thickest between midnight and about nine in the morning from December to February, and it forms first over the low ground near the rivers and the Kanchan and Ulukhola bridges. Dipped headlights, not full beam: full beam reflects off the fog and shortens what you can see. Use the fog lamps if the vehicle has them, slow to a speed you can stop within the distance you can see, keep well back from the tail lights ahead, and do not stop on the carriageway. If you must stop, leave the road at the next exit or pull fully onto the hard shoulder with hazard lights on.</p><p>The readings above come from a weather model at three points along the road, not from sensors on it. They are a warning to expect fog, not a guarantee of its absence.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"কুয়াশায় ড্রাইভিং","body":"<p>এই করিডোরে ডিসেম্বর থেকে ফেব্রুয়ারিতে মধ্যরাত থেকে সকাল নয়টা পর্যন্ত কুয়াশা সবচেয়ে ঘন হয়, আর নদীর কাছের নিচু জমি এবং কাঞ্চন ও উলুখোলা ব্রিজের ওপর আগে জমে। হাই বিম নয়, লো বিম জ্বালান: হাই বিম কুয়াশায় প্রতিফলিত হয়ে দৃষ্টিসীমা আরও কমিয়ে দেয়। গাড়িতে ফগ লাইট থাকলে জ্বালান, যতটুকু দেখছেন তার মধ্যে থামতে পারেন এমন গতিতে চালান, সামনের গাড়ির টেল লাইট থেকে দূরে থাকুন এবং মূল রাস্তায় থামবেন না। থামতেই হলে পরের এক্সিটে বেরিয়ে যান বা হ্যাজার্ড লাইট জ্বালিয়ে পুরোপুরি হার্ড শোল্ডারে উঠে যান।</p><p>ওপরের তথ্য রাস্তার তিনটি জায়গার আবহাওয়া মডেল থেকে আসে, রাস্তার সেন্সর থেকে নয়। এটি কুয়াশার জন্য তৈরি থাকার সতর্কতা, কুয়াশা নেই তার নিশ্চয়তা নয়।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"雾天驾驶","body":"<p>本走廊的雾在 12 月至 2 月的午夜至上午九点前后最浓，最先在河流附近的低洼地带以及 Kanchan 桥和 Ulukhola 桥上形成。请开近光灯而非远光灯：远光灯会被雾反射，反而缩短视距。有雾灯请打开，把车速降到在可视距离内能停下的程度，与前车尾灯保持足够距离，不要在主路上停车。如必须停车，请在下一个出口驶离，或完全驶入硬路肩并打开危险警示灯。</p><p>上方读数来自道路沿线三个点的天气模型，而非路侧传感器。它是提醒您可能有雾，而不是保证没有雾。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;

