INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"eyebrow":"তথ্য প্রকাশ","heading":"ওপেন ডেটা","lede":"এই সাইটের তথ্য এমন ফরম্যাটে, যা ডিসপ্যাচারের স্ক্রিন, গবেষকের স্প্রেডশিট বা নিউজরুমের ম্যাপ সরাসরি পড়তে পারে। একই রেকর্ড, একই সময়, একই চিহ্ন।"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
