SET @b = IF(@fresh = 1, LAST_INSERT_ID(), NULL);
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"What the feeds are, and are not","body":"<p>Every feed is built from the same records the pages read, at the moment it is requested, and carries the same flags: a <code>traffic_source</code> of <code>sample</code> means the conditions describe nothing real, and a monthly row marked <code>sample</code> is a placeholder DBEDC has not yet replaced. Treat those rows as the site does, as examples of the shape, not as measurements.</p><p>No feed contains anything about a person: no number plates, no account details, no camera images. The traffic measurements are journey speeds over each section from a routing provider, sampled every half hour while the live feed runs.</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"ফিডগুলো কী, আর কী নয়","body":"<p>প্রতিটি ফিড পেজগুলো যে রেকর্ড পড়ে সেই রেকর্ড থেকেই, চাওয়ার মুহূর্তে তৈরি হয় এবং একই চিহ্ন বহন করে: <code>traffic_source</code> যদি <code>sample</code> হয়, তবে ওই অবস্থা বাস্তব কিছু বোঝায় না; আর <code>sample</code> চিহ্নিত মাসিক সারি DBEDC এখনো বদলায়নি এমন নমুনা। এই সারিগুলোকে সাইট যেভাবে দেখে সেভাবেই দেখুন: ফরম্যাটের উদাহরণ, পরিমাপ নয়।</p><p>কোনো ফিডে কারও ব্যক্তিগত কিছু নেই: গাড়ির নম্বর নেই, অ্যাকাউন্টের তথ্য নেই, ক্যামেরার ছবি নেই। ট্রাফিক পরিমাপ হলো রাউটিং সার্ভিস থেকে পাওয়া প্রতিটি অংশের যাত্রার গতি, লাইভ ফিড চলার সময় প্রতি আধা ঘণ্টায় নেওয়া।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"数据是什么，不是什么","body":"<p>每个数据源都在被请求的那一刻由页面所读取的同一批记录生成，并带有相同的标记：<code>traffic_source</code> 为 <code>sample</code> 表示路况不代表任何真实情况；标记为 <code>sample</code> 的月度行是 DBEDC 尚未替换的占位数据。请像本网站一样对待这些行：它们是格式示例，而非监测结果。</p><p>任何数据源都不包含个人信息：没有车牌、没有账户信息、没有摄像头图像。交通监测数据是来自路径规划服务的各路段行程车速，在实时数据运行期间每半小时采样一次。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;

-- ---------------------------------------------------------------- km-finder on travel/breakdown
SET @p = (SELECT `id` FROM `pages` WHERE `slug` = 'travel/breakdown');
SET @has = (SELECT COUNT(*) FROM `blocks` WHERE `page_id` = @p AND `type` = 'km-finder');
SET @ok = (@p IS NOT NULL AND @has = 0);
SET @anchor = (SELECT `sort_order` FROM `blocks` WHERE `page_id` = @p AND `type` = 'emergency-strip' ORDER BY `sort_order` LIMIT 1);
SET @anchor = COALESCE(@anchor, (SELECT MAX(`sort_order`) FROM `blocks` WHERE `page_id` = @p), -1);
UPDATE `blocks` SET `sort_order` = `sort_order` + 1 WHERE `page_id` = @p AND @ok AND `sort_order` > @anchor;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'km-finder', @anchor + 1, 'published' FROM DUAL WHERE @ok;
SET @b = IF(@ok, LAST_INSERT_ID(), NULL);
