-- ---------------------------------------------------------------- concession-scorecard on about/concession
SET @p = (SELECT `id` FROM `pages` WHERE `slug` = 'about/concession');
SET @has = (SELECT COUNT(*) FROM `blocks` WHERE `page_id` = @p AND `type` = 'concession-scorecard');
SET @ok = (@p IS NOT NULL AND @has = 0);
SET @last = (SELECT `id` FROM `blocks` WHERE `page_id` = @p ORDER BY `sort_order` DESC, `id` DESC LIMIT 1);
SET @lastsort = (SELECT `sort_order` FROM `blocks` WHERE `id` = @last);
SET @endcta = (SELECT `type` = 'cta-band' FROM `blocks` WHERE `id` = @last);
UPDATE `blocks` SET `sort_order` = `sort_order` + 1 WHERE `id` = @last AND @ok AND @endcta = 1;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'concession-scorecard', IF(@endcta = 1, @lastsort, COALESCE(@lastsort, 0) + 1), 'published' FROM DUAL WHERE @ok;
SET @b = IF(@ok, LAST_INSERT_ID(), NULL);
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Concession scorecard","intro":"The term of the concession and the obligations DBEDC reports against, target beside achieved, each with its source and date. Figures appear as DBEDC publishes them.","termLabel":"","termStart":"","termEnd":"","termSource":"","rows":[],"emptyMessage":""}', 'published' FROM DUAL WHERE @b IS NOT NULL;
