-- ---------------------------------------------------------------- menus, labelled from the pages
SET @m = (SELECT `id` FROM `menus` WHERE `slug` = 'travel');
SET @n = (SELECT COUNT(*) FROM `menu_items` WHERE `menu_id` = @m AND `href` = 'travel/locate');
SET @next = (SELECT COALESCE(MAX(`sort_order`), 0) + 10 FROM `menu_items` WHERE `menu_id` = @m);
INSERT INTO `menu_items` (`menu_id`, `href`, `labels`, `sort_order`)
  SELECT @m, 'travel/locate', JSON_OBJECT(
      'en', COALESCE((SELECT `title` FROM `page_translations` WHERE `page_id` = p.`id` AND `locale` = 'en'), ''),
      'bn', COALESCE((SELECT `title` FROM `page_translations` WHERE `page_id` = p.`id` AND `locale` = 'bn'), ''),
      'zh', COALESCE((SELECT `title` FROM `page_translations` WHERE `page_id` = p.`id` AND `locale` = 'zh'), '')
    ), @next
    FROM `pages` p
   WHERE p.`slug` = 'travel/locate' AND p.`status` = 'published' AND @m IS NOT NULL AND @n = 0;
